class AsyncProvidersMtsQrResource(AsyncResource):
    """Operations of `client.providers.mts.qr`."""

    async def info(
        self,
        *,
        qr_data: str,
        **options: Unpack[RequestOptions],
    ) -> MtsQrInfo:
        """Decode an SBP QR code.

        First step of paying a Russian merchant's SBP (Faster Payments System) QR code from the
        Whitebird balance. The request carries the scanned QR content; the response is a payment
        ticket (`qrTicketId`) used by the next steps:

        1. Check `error.code`: anything but `0` is a failure described by `error.message`
           (in Russian; e.g. code `102` means the QR code was not found). The web app also refuses
           tickets with more than one entry in `payments`.
        2. For a static QR code (`payments[0].qrType == "static"`) the payer chooses the amount
           and gets the amount to pay from `commission`; otherwise the amount is
           `payments[0].settlementAmount`.
        3. Pay through the exchange API: from a RUB balance, first
           `balance.withdrawals.calculate_fiat` with `fiatProviderType: MTS_QR`,
           `paymentToken: qrTicketId`, `commissionType: ADD` and the amount, then
           `balance.withdrawals.create_fiat` with the same fields plus `accountType`; or by selling
           crypto with a quote whose output is `{type: FIAT_PROVIDER, provider: MTS_QR,
           token: qrTicketId}`.

        Args:
            qr_data: Raw content of the scanned SBP QR code.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `MtsQrInfo`.
        """
        return await self._engine.request(
            "mts",
            "POST",
            "/api/v1/qr/info",
            json={"qrData": qr_data},
            cast_to=MtsQrInfo,
            options=options,
        )

    async def commission(
        self,
        *,
        qr_ticket_id: str,
        amount: Decimal | float,
        **options: Unpack[RequestOptions],
    ) -> MtsQrCommission:
        """Calculate the amount to pay for a static SBP QR code.

        Used for static QR codes, where the payer enters the amount. The returned `amount` is what
        the web app then pays (see `info` for the whole flow).

        Args:
            qr_ticket_id: Ticket returned by `info`.
            amount: Amount the payer entered, in the QR code's currency.
            **options: Per-request options, see `RequestOptions`.

        Note:
            Experimental: the endpoint may change or disappear without notice. Reconstructed from
            the Whitebird web application; fields may be missing.

        Returns:
            The response as `MtsQrCommission`.
        """
        return await self._engine.request(
            "mts",
            "POST",
            "/api/v1/qr/payment/commission",
            json={"qrTicketId": qr_ticket_id, "amount": amount},
            cast_to=MtsQrCommission,
            options=options,
        )


